-- Apply after 020. One filtered dataset supplies record pages and accurate tab counts.
begin;
do $$begin if not exists(select 1 from public.jf_schema_versions where version='020_direct_record_panels') then raise exception 'Apply migration 020 first.';end if;end$$;
create or replace function public.jf_workspace_page(target_shop uuid,entity text,filters jsonb default '{}',page_number integer default 0) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;st text:=coalesce(filters->>'status','all');search text:=trim(coalesce(filters->>'search',''));agent_id uuid:=nullif(filters->>'agent_id','')::uuid;
begin
 if page_number is null or page_number<0 or length(search)>200 then raise exception 'Invalid page filter.';end if;
 if entity='customers' then
  with base as materialized(select c.*,f.status followup_status,f.call_outcome,f.callback_at,(buyers.customer_id is not null) has_confirmed from public.jf_customers c left join public.jf_followups f on f.shop_id=c.shop_id and f.customer_id=c.id left join (select distinct x.customer_id from public.jf_orders x where x.shop_id=target_shop and x.archived_at is null and x.status not in('draft','cancelled')) buyers on buyers.customer_id=c.id where c.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and (coalesce(filters->>'response','')='' or f.call_outcome=lower(filters->>'response')) and (coalesce(filters->>'call','')='' or lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')) and (search='' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%')),c as(select * from base c where (st='confirmed' and c.has_confirmed or st='attempted' and c.call_outcome is not null and c.call_outcome<>'not_attempted' or st='failed' and c.call_outcome is not null and c.call_outcome<>'not_attempted' and not c.has_confirmed or lower(replace(c.workflow_label,' ','_'))=st or st in('no_answer','busy') and c.call_outcome=st or st='all' or st='unassigned' and c.assigned_membership_id is null or st='assigned' and c.assigned_membership_id is not null or st='permanent' and c.permanent or st='completed' and c.followup_status='completed' or st='pending' and coalesce(c.followup_status,'pending') in ('pending','callback') or st='cancelled' and c.followup_status='cancelled' or st='connected' and c.call_outcome in ('connected','positive','negative','intermediate') or st='not_connected' and c.call_outcome in ('not_connected','no_answer','busy') or st='not_attempted' and (c.call_outcome is null or c.call_outcome='not_attempted') or st in ('positive','negative','intermediate') and c.call_outcome=st or st='callback' and c.followup_status='callback' or st='callbacks' and c.followup_status='callback' and c.callback_at<=now() or st='buyers' and c.followup_status='completed' and c.has_confirmed))
  select jsonb_build_object('counts',coalesce((select jsonb_object_agg(k,n) from(select lower(replace(workflow_label,' ','_')) k,count(*) n from base where nullif(workflow_label,'') is not null group by 1) labels),'{}'::jsonb)||(select jsonb_build_object('all',count(*) filter(where true),'assigned',count(*) filter(where assigned_membership_id is not null),'unassigned',count(*) filter(where assigned_membership_id is null),'completed',count(*) filter(where followup_status='completed'),'pending',count(*) filter(where coalesce(followup_status,'pending') in('pending','callback')),'cancelled',count(*) filter(where followup_status='cancelled'),'permanent',count(*) filter(where permanent),'connected',count(*) filter(where call_outcome in('connected','positive','negative','intermediate')),'not_connected',count(*) filter(where call_outcome in('not_connected','no_answer','busy')),'not_attempted',count(*) filter(where call_outcome is null or call_outcome='not_attempted'),'attempted',count(*) filter(where call_outcome is not null and call_outcome<>'not_attempted'),'confirmed',count(*) filter(where has_confirmed),'failed',count(*) filter(where call_outcome is not null and call_outcome<>'not_attempted' and not has_confirmed),'buyers',count(*) filter(where followup_status='completed' and has_confirmed),'callback',count(*) filter(where followup_status='callback'),'callbacks',count(*) filter(where followup_status='callback' and callback_at<=now()),'positive',count(*) filter(where call_outcome='positive'),'negative',count(*) filter(where call_outcome='negative'),'intermediate',count(*) filter(where call_outcome='intermediate'),'no_answer',count(*) filter(where call_outcome='no_answer'),'busy',count(*) filter(where call_outcome='busy')) from base),'total',(select count(*) from c),'rows',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('latest_note',(select n.body from public.jf_notes n where n.shop_id=target_shop and n.customer_id=p.id order by n.created_at desc,n.id desc limit 1),'order_count',(select count(*) from public.jf_orders z where z.shop_id=target_shop and z.customer_id=p.id and z.archived_at is null))) from(select * from c order by updated_at desc,id limit 50 offset page_number::bigint*50) p),'[]')) into result;
 elsif entity='orders' then
  with base as materialized(select o.* from public.jf_orders o where o.shop_id=target_shop and o.archived_at is null and (agent_id is null or o.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or o.created_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or o.created_at<(filters->>'report_end')::timestamptz) and (coalesce(filters->>'source','')='' or case when lower(o.source) in('website','facebook','whatsapp') then lower(o.source) else 'other' end=filters->>'source') and (nullif(filters->>'product_id','') is null or exists(select 1 from public.jf_order_items i where i.shop_id=target_shop and i.order_id=o.id and i.product_id=(filters->>'product_id')::uuid)) and (coalesce(filters->>'tag','')='' or exists(select 1 from public.jf_customers c where c.shop_id=target_shop and c.id=o.customer_id and c.unassignment_tag=filters->>'tag')) and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')))) and (search='' or o.order_number ilike '%'||search||'%' or o.recipient_name ilike '%'||search||'%' or o.recipient_phone ilike '%'||search||'%')),o as(select * from base o where (st='all' or st='confirmed' and o.status not in ('draft','cancelled') or st='ready_to_book' and o.status in ('confirmed','ready_to_book') or st not in ('confirmed','ready_to_book') and o.status=st))
  select jsonb_build_object('counts',(select jsonb_build_object('all',count(*) filter(where true),'confirmed',count(*) filter(where status not in('draft','cancelled')),'ready_to_book',count(*) filter(where status in('confirmed','ready_to_book')),'draft',count(*) filter(where status='draft'),'booked',count(*) filter(where status='booked'),'in_transit',count(*) filter(where status='in_transit'),'delivered',count(*) filter(where status='delivered'),'partial_delivery',count(*) filter(where status='partial_delivery'),'returned',count(*) filter(where status='returned'),'cancelled',count(*) filter(where status='cancelled'),'exchange',count(*) filter(where status='exchange'),'replacement',count(*) filter(where status='replacement')) from base),'total',(select count(*) from o),'rows',coalesce((select jsonb_agg(to_jsonb(p)) from(select * from o order by created_at desc,id limit 50 offset page_number::bigint*50) p),'[]')) into result;

  -- Imported history is a separate, read-only ledger, never a new courier order.
  with h as(select h.id,h.external_id order_number,c.full_name recipient_name,c.phone recipient_phone,c.address delivery_address,c.source,c.assigned_membership_id,h.customer_id,h.updated_at created_at,h.updated_at,'imported'::text status,true is_imported,h.details,case when coalesce(h.details->>'total','') ~ '^[0-9]+([.][0-9]+)?$' then (h.details->>'total')::numeric else 0 end total
   from public.jf_order_history h join public.jf_customers c on c.shop_id=h.shop_id and c.id=h.customer_id where h.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or h.updated_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or h.updated_at<(filters->>'report_end')::timestamptz)
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and nullif(filters->>'product_id','') is null
   and (search='' or h.external_id ilike '%'||search||'%' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%'))
  select result||jsonb_build_object('counts',(result->'counts')||jsonb_build_object('imported',(select count(*) from h)))||case when st='imported' then jsonb_build_object('total',(select count(*) from h),'rows',coalesce((select jsonb_agg(to_jsonb(p)) from(select * from h order by updated_at desc,id limit 50 offset page_number::bigint*50)p),'[]')) else '{}'::jsonb end into result;
 else raise exception 'Choose customers or orders.';end if;
 return result;
end $$;

insert into public.jf_schema_versions(version) values('021_inline_tab_counts');commit;
